/* Learner handbook: each chapter links to the actual Academy workflow. */
(() => {
'use strict';
const action=(label,href)=>`<a class="btn" href="${href}">${label} →</a>`;
const note=text=>`<div class="guide-callout"><p>${text}</p></div>`;
const table=(heads,rows)=>`<div class="guide-table-wrap"><table><thead><tr>${heads.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const chapters=[
{id:'start',title:'Start here',intro:'A calm, practical route from “I have never done this” to work you can explain and defend.',body:()=>`
<p>The Academy teaches through tasks. You read a short brief, make something, check it and keep the evidence. You can pause between steps and return to your draft on the same browser.</p>
<h3>Your first 30 minutes</h3><ol><li><strong>Choose a direction — 5 minutes.</strong> Open <a href="#paths">Browse courses</a>. If you are new to digital work, choose Digital confidence. Read what you will build and the planned practice time.</li><li><strong>Check access — 2 minutes.</strong> Free foundations need completed registration and no checkout. Other pathways open only with an active purchase or assigned access.</li><li><strong>Open the first project — 8 minutes.</strong> Select “Open next project.” Read the task, ingredients and acceptance criteria. Write your own understanding of the goal.</li><li><strong>Make a first attempt — 10 minutes.</strong> Follow the next unlocked step and use the tool when the recipe asks you to. A small, testable attempt is enough to start.</li><li><strong>Keep your work — 5 minutes.</strong> Check the saved-draft message, export a backup and add a realistic next session to your Learning planner.</li></ol>
<h3>One Academy, two practice formats</h3><div class="guide-grid"><div><h3>Guided pathways</h3><p>Eighteen courses with ten projects each, grouped into five named modules. Six steps per project, progressing through five difficulty levels. Start here when you want a clear, focused learning route.</p></div><div><h3>Professional practice</h3><p>The original Professional Practice Workspace: 48 programmes, 192 missions and twelve stages per mission. Use it for deeper specialist briefs, simulations, failure investigations and evidence preparation.</p></div></div>
${note('Your guided projects and professional missions keep their own evidence records inside the same Academy. Completing one does not automatically complete the other. Choose one task at a time.')}
<div class="guide-path"><a href="#paths"><small>01 / CHOOSE</small>Find your first pathway</a><a href="workspace.html"><small>02 / APPLY</small>Explore professional practice</a><a href="#calendar"><small>03 / RETURN</small>Plan your next session</a></div>`},
{id:'account',title:'Register & sign in',intro:'Sign in securely, complete your learner profile, then open your Academy.',body:()=>`
<h3>Create a learner account</h3><ol><li>Open the Academy and select <strong>Register</strong>. Account entry shows only sign-in and registration; course navigation is available after setup.</li><li>Enter your email and a unique password of 12–128 characters. Open the confirmation link sent to your email, then continue to your Academy profile.</li><li>Complete your learner profile: full name, optional country, free foundation starting point and realistic weekly hours.</li><li>Read and accept the storage consent, then select <strong>Create my account & enter Academy</strong>. Your profile and consent are saved to your account.</li><li>Your dashboard opens with the two free foundations. Browse other courses and review their purchase terms when you are ready. Registration gives you the learner role; it does not create paid access or staff permissions.</li></ol>
<h3>Return to the Academy</h3><p>Enter your email and password, then open your courses. If you signed in but have not completed registration, the Academy returns you to your profile form. Direct course, practice, guide and tool links follow the same rule.</p>
<h3>Your profile and sign-out</h3><p>Open <strong>My account</strong> to update your name, starting course and weekly hours. Use <strong>Sign out</strong> to end secure access. The sidebar is available only inside your registered learning workspace. Signing out and using the browser’s Back button do not reopen protected content.</p>
<h3>Password recovery</h3><p>Select <strong>Forgot password?</strong> on sign-in, enter your account email and open the recovery link. Set a new 12–128-character password, then sign in again.</p>
${note('If secure sign-in is temporarily unavailable, Academy content stays locked. Retry from the account page; there is no anonymous preview shortcut. Certificate QR lookup checks only its public issued record and has no Academy navigation.')}
<div class="guide-actions">${action('My account',window.AcademyShell.accountURL('account'))}${action('Sign in',window.AcademyShell.accountURL('sign-in'))}</div>`},

{id:'navigation',title:'Find your way around',intro:'Know which part of the Academy to open for each job.',body:()=>`
${table(['Where','What to do there'],[['My learning journey','Find your recommended next project, weekly activity and quick links.'],['Browse courses','Compare the eighteen courses, outcomes, five levels and project sequence.'],['Access & receipts','Check purchase availability, access and owned orders. Open the receipt for a confirmed payment.'],['Learning planner','Set the date, time and length of a practice session; download it as a calendar event.'],['My workspace','Use the eleven guided-project tools and return to your current recipe.'],['Professional practice','Enter the original twelve-stage missions, specialist tools, labs and evidence centre.'],['Projects & assessment','See guided-project practice, inspect feedback and submit eligible work for qualified review.'],['My progress','See your recorded guided-project activity and pathway progress.'],['Certificates','See the sample design and, when eligible, request an assessed pathway certificate.'],['Programme library','Search all 48 professional programmes and open a programme’s first mission.'],['Academy guide / glossary','Read these instructions or look up an unfamiliar word.']])}
<p>On a small screen, use the menu button at the top left. Escape closes navigation. In the dashboard, use the search button or <strong>Ctrl K / Command K</strong> to find a pathway, recipe, tool or guide chapter.</p>
<p>Inside Professional Practice, open <strong>Workspace sections</strong> to choose the mission, tool library, evidence centre, services or support preparation. The Academy sidebar remains your route back to guided learning.</p>
<div class="guide-actions">${action('Open dashboard','#home')}${action('Browse programmes','#programmes')}</div>`},
{id:'pathways',title:'Browse courses & pace',intro:'Begin with foundations, then work through progressively harder tasks.',body:()=>`
<ol><li>Open <strong>Browse courses</strong> and search by the skill you want. Read the summary and outcome before committing.</li><li>Open the pathway to see all ten projects, grouped into Beginner, Builder, Professional, Advanced and Expert practice.</li><li>Check the starting point. If the topic assumes digital foundations, build that confidence first. Planned hours are estimates, so leave time for corrections.</li><li>Select <strong>Start / continue this pathway</strong>. If access is needed, the Academy takes you to the access options. Otherwise, you start the next unfinished project.</li><li>Set your weekly pace in <strong>My learning preferences</strong> on the home page. Use the planner for individual sessions that fit your schedule.</li></ol>
<h3>A sustainable weekly session</h3><p>Spend a few minutes recalling the last task, most of your session building and testing, and the final few minutes recording what happened. When you get stuck, write down the exact error and one change you will try next. Return to the same project instead of opening many unfinished projects.</p>
${note('Advanced and Expert describe the task’s difficulty. Practice completion is useful evidence of effort; professional expertise also requires reliable real-world delivery and qualified assessment.')}
<div class="guide-actions">${action('Browse courses','#paths')}${action('Set my learning preferences','#onboarding')}${action('Plan a session','#calendar')}</div>`},
{id:'plan',title:'Plan your guided or professional route',intro:'Choose one format, one skill and a realistic weekly practice budget.',body:()=>`
<h3>Set up your weekly plan</h3><ol><li>Open <strong>My learning plan</strong> in the sidebar.</li><li>Choose <strong>Guided Learning</strong> if the skill is new, or <strong>Professional Practice</strong> if you want to apply an existing skill to a complete working brief.</li><li>Select a free or accessible course or programme. Purchased learning stays within your active course scope.</li><li>Set weekly hours, practice days and your timezone, then choose <strong>Save my weekly plan</strong>.</li><li>Use the new “Open my planned course” or “Open my professional programme” link. Your saved route also appears in My courses.</li></ol>
<h3>A guided session</h3><p>Read the short explanation. Explain it in your own words, using writing or the voice-typing control when your browser supports it. Build the small work product, test an ordinary case and a failure, reflect on what changed, then save and submit the evidence when ready. Finish the current project before opening the next project.</p>
<h3>A professional session</h3><p>Read the brief and follow the 12-stage mission rail. Learn, inspect, simulate, build, break, fix, test, explain, defend, ship and prepare evidence. Use the recommended tools at the relevant stage. Save a cloud snapshot through Reviews, records & payments before changing devices.</p>
<h3>Keep time and evidence clear</h3><p>The weekly plan is saved to your account. Session calendar entries and tool drafts remain on your device until exported or explicitly saved through their cloud workflow. My activity displays actual saved Academy actions; it does not turn a visit into a grade. Teacher bundles use their separately agreed class schedule.</p>
<div class="guide-actions">${action('Set my learning plan','#plan')}${action('My activity','#activity')}${action('Schedule a session','#calendar')}</div>`},
{id:'recipes',title:'Complete a guided project',intro:'Six steps take you from understanding the task to a clear evidence package.',body:()=>`
${table(['Step','Your work'],[['1. Understand','Read the brief and acceptance criteria. Write what you will make, who it helps and what a successful result must do.'],['2. Explain in your own words','Explain what you understood, relate it to the worked example, name a source fact and identify an assumption. Type or use Dictate my explanation, then review the text.'],['3. Build','Build in the suggested tool. Keep the work product and explain what you changed.'],['4. Test & fix','Test the expected case and at least one failure case. Record the actual result and inspect every acceptance criterion.'],['5. Reflect','Describe your decisions, alternatives, limitations and what you would improve.'],['6. Submit evidence','Write a handover, confirm evidence consent, check the evidence structure and export or submit the work.']])}
<p>Use <strong>Save step & continue</strong> to advance. Later steps unlock after the required notes are present; step four also requires you to inspect the criteria. If a check fails, read the message and improve the relevant section before trying again.</p>
<h3>What good evidence looks like</h3><p>“It worked” is too vague. Prefer: “Expected: a missing approval blocks release. Actual: release was denied. After recording the approval, I repeated the test and the approved file became available.” Use fictional or permissioned data in your exercises.</p>
<p><strong>Complete practice recipe</strong> records local practice when the evidence requirements pass. <strong>Save to cloud</strong> and submission actions are available when the connected account and pathway permit them. Structural checks assess completeness; a qualified person assesses the quality of your work.</p>
<div class="guide-actions">${action('Start Digital confidence','#path/start')}${action('Open my projects','#portfolio')}</div>`},
{id:'professional',title:'Use professional practice',intro:'The original Professional Practice Workspace is part of the Academy, with all 48 programmes and 192 missions preserved.',body:()=>`
<h3>Open the right mission</h3><ol><li>Open <strong>Practice workspace</strong> from the sidebar, then select <strong>Professional Practice Workspace</strong>. Use “Continue mission” to resume your current programme, or open <strong>Workspace sections → Explore programmes</strong>.</li><li>If you are a beginner, start with <strong>DB-00</strong>. For a specialist subject, read its programme summary and recommended route before opening the mission.</li><li>Read the scenario and move through the twelve stages in order. Each stage has its own evidence gate; a failed gate explains what you need to add or rerun.</li><li>Use the mentor walkthrough and explanations where offered. Make your own attempt and inspect the result before relying on hints.</li></ol>
${table(['Stage','What to do'],[['Brief','Understand the client problem, constraints and definition of success.'],['Learn','Work through the preparation units and check your understanding.'],['Investigate','Inspect the source material and record the relevant facts.'],['Try','Make a small first attempt in the mission’s tool.'],['Build','Develop the complete work product for the brief.'],['Break','Test an invalid input, denied action or other failure case.'],['Fix','Correct the cause, then rerun the affected work.'],['Test','Run current checks and keep the observed results.'],['Explain','Describe your decisions and the evidence supporting them.'],['Defend','Answer challenges, acknowledge limitations and justify your approach.'],['Ship','Prepare the checked handover. This is a practice release, not an external deployment.'],['Evidence','Finish and preserve the mission attempt with its work and checks.']])}
<h3>Use the supporting sections</h3><p><strong>Tool library</strong> opens the programme that uses a specialist tool. <strong>Simulation labs</strong> provide operating queues and cases. <strong>Failure Passport</strong> records what went wrong and how you corrected it. <strong>Evidence centre</strong> holds local packs and backup controls. <strong>Assessment centre</strong> prepares your assessment scope; <strong>Reviews, records & payments</strong> connects eligible accounts to actual cloud submissions and service requests.</p>
${note('Editing a work product can invalidate earlier tests and shipping evidence. Rerun the checks on the new revision before finishing. A local evidence pack is not a verified certificate.')}
<div class="guide-actions">${action('Open Professional Practice Workspace','workspace.html')}${action('Start DB-00','workspace.html?programme=DB-00')}${action('Open evidence centre','workspace.html?view=evidence')}</div>`},
{id:'tools',title:'Work with the tools',intro:'Keep your project brief nearby while you make, test and explain the work.',body:()=>`
${table(['Tool','How to use it'],[['Writing desk','Draft notes, decisions, briefs or handovers. Copy useful evidence back into the relevant recipe step and export when needed.'],['Web studio','Edit HTML and run the preview. Check layout, focus and behaviour. Code runs inside a restricted preview frame.'],['Data desk','Paste the exercise CSV and calculate its summary, or run a supported SELECT query against the training data. Inspect invalid and missing values.'],['Prompt studio','Specify the task, context and constraints; build a prompt you can review and reuse. This tool constructs prompts and does not call an AI model.'],['Automation lab','Set the exercise workflow and run its simulation. Inspect retries, ordering and failure handling; it does not run a live business automation.'],['API console','Choose the simulated actor and request. Compare allowed and denied results. This is a training API, not access to an external account.']])}
<p>The Design desk exports an announcement as SVG; the Project board saves tasks, owners and acceptance checks; the Budget calculator shows a scenario calculation; the JSON inspector validates structured data; the Contrast checker measures text readability.</p><p>Open <a href="#tools">Tools & services</a> to search external tools by task and Free, Freemium or Paid. Canva, Figma, ChatGPT, Claude, Hugging Face, Ollama, OpenCode, Replit, Lovable, Render, Vercel, GoDaddy and Hostinger open in their own workspace. Their subscriptions are separate from your Academy purchase. Your lesson recommends a small relevant set. Do not paste private keys or confidential client records into practice evidence.</p>Use <strong>Return to my recipe</strong> in My workspace to continue the last guided project. Tool drafts save separately from recipe notes, so paste or describe the relevant output in the recipe’s evidence fields. Use the export controls to keep the actual work.</p>
<p>For permission matrices, ledgers, file intake, event ordering and professional case desks, open the specialist links below the tools or the Professional Practice Tool library. Each tool belongs to a mission with its own checks.</p>
${note('The receipt printer is a payment confirmation animation in Access & receipts. It is not a manufacturing or 3D design tool.')}
<div class="guide-actions">${action('Open My workspace','#studio')}${action('Open specialist tools','workspace.html?view=tools')}</div>`},
{id:'teaching',title:'Learn with your teacher',intro:'A dedicated course bundle adds eight weeks of private teaching to your purchased course.',body:()=>`<h3>What the supported bundle includes</h3><p>The bundle is 24 individual classes, each two hours long, with three classes per week over eight weeks. That is 48 hours of teaching. Course access follows the duration shown in the purchase terms; the teaching period is agreed when your teacher is assigned.</p><h3>Start after confirmed purchase</h3><ol><li>Open the chosen course in Browse courses and select its supported bundle when enrolment is available. Review the price, included course, refund terms and teaching commitment before paying.</li><li>After confirmed payment, open <strong>My teacher</strong>. Your package first shows <strong>Awaiting teacher</strong>. A named qualified mentor is appointed by the Academy; a preview does not create a fictional teacher.</li><li>Save your preferred days, times and timezone. Your teacher and the Academy agree the start of the eight-week period and offer actual available class times.</li><li>Book a time from the offered list. It must fall within the teaching period, and cannot overlap another booked class. You can book up to three classes in each package week and 24 in total.</li><li>Check the displayed time in your device timezone. Open the Google Meet, Zoom or Teams link in the booking. If the link is pending, return later or contact the Academy through its service request desk.</li></ol><h3>Before, during and after a class</h3><p>Before class, read the next lesson and prepare one question or failed test. During class, explain the concept, make your own attempt and inspect the result with your teacher. After class, complete the recipe evidence and review the teacher's actual attendance and learning notes in My teacher.</p><h3>Changes and assessment</h3><p>You may cancel a future booking in your dashboard and choose another offered time within the package limits. A teacher cancellation appears with its reason and next action. A suspended or refunded package stops further booking and meeting-link access. Contact the Academy about classes that have already started, exceptional rescheduling or an appeal.</p><p>Teaching supports learning; it does not automatically pass your work. Qualified assessment and separate independent verification are still required before a certificate can be issued.</p><div class="guide-actions">${action('Open My teacher','#teaching')}${action('Review bundles','#shop')}</div>`},
{id:'access',title:'Access, payment & receipts',intro:'Understand what is included before you pay, and keep the receipt after confirmation.',body:()=>`<h3>Choose an available payment method</h3><p>Card checkout uses protected Stripe fields for Visa, Mastercard and other eligible methods. Google Pay appears only when supported by your device, region and merchant settings. The card graphic reacts to payment method and completion; the Academy cannot read the full card number.</p><p>Gumroad checkout opens the approved product. Use the same email as your Academy account, then link the purchase ID from its receipt so the server can verify the merchant record. Binance Pay opens a merchant wallet checkout. Other supported wallets use an approved crypto gateway; select the exact asset and network and send the stated amount. A pending or partial transfer does not unlock a course.</p><p>Methods unavailable for a course are disabled. A visual sample is not a payment and never changes your access. A verified full refund or dispute revokes access created by that order and suspends its teaching package.</p>
<ol><li>Choose your pathway, then open <strong>Access & receipts</strong>. Review the listed scope, availability and purchase terms. Free foundations do not need checkout.</li><li>If an approved live product is available, accept the terms and use its checkout button. Payment takes place on the supported payment provider’s checkout page.</li><li>After you return, wait for the Academy to confirm the payment. Returning from checkout or opening a success-looking URL cannot unlock a course by itself.</li><li>Once the payment is confirmed, your owned order gets a receipt and the purchased access is updated. The receipt animates as paper feeding from a three-dimensional printer.</li><li>Print or download your actual receipt, then continue to the unlocked pathway. You can reopen the order from Access & receipts.</li></ol>
<h3>If something interrupts checkout</h3><p>An unpaid, cancelled or expired checkout creates no new learning access. For a pending payment, use the receipt page’s refresh control after allowing time for confirmation. If your provider shows a charge but the Academy still shows pending, keep the order reference and request help before paying again.</p>
<p>Refunds and disputes can change the order status and learning access. The receipt record shows the original payment and any recorded refund information. Submit refund questions through the service desk when it is connected.</p>
${note('The current practice preview does not charge money or create paid receipts. “Preview the receipt animation” is explicitly marked SAMPLE and does not grant access. Buying learning access does not buy a certificate or a staff role.')}
<div class="guide-actions">${action('Access & receipts','#shop')}${action('See sample receipt animation','#receipt/demo')}</div>`},
{id:'roles',title:'Understand roles & privacy',intro:'Your identity, purchased learning access and staff responsibilities are separate.',body:()=>`
${table(['Role or access','What it means'],[['Learner','Practice, save your own work, view your owned orders and submit eligible evidence. Your account cannot approve its own assessment.'],['Pathway access','An active purchase or owner assignment unlocks its stated learning scope. Access can expire or change after a refund. It does not make you a reviewer.'],['Reviewer','A qualified person appointed for an approved subject scope assesses assigned submissions and gives evidence-backed feedback.'],['Verifier','A different qualified person checks the review and evidence independently. The learner, reviewer and verifier must be separate people.'],['Owner','Manages approved access, staff appointments and Academy operations. Administrative access does not bypass independent assessment requirements.']])}
<h3>Your work and personal details</h3><p>Browser drafts stay on the device. Connected cloud records belong to your account and are made available only to the people authorized for the relevant learning or operational task. Use fictional examples for practice and remove private client information before submitting evidence.</p>
<p>A certificate’s public verification record can display the name and scope you consent to share. Read the consent before requesting an issued certificate. You can keep local practice and unissued evidence private.</p>
${note('Registration is mandatory. Only free courses and the courses assigned to or purchased by your verified account can open. Staff controls and learner records have their own server-side permissions.')}
<div class="guide-actions">${action('Review my access','#shop')}${action('Read assessment requirements','#guide/assessment')}</div>`},
{id:'assessment',title:'Assessment & certificates',intro:'Move from a practice attempt to a reviewed and independently verified record.',body:()=>`
<h3>For guided pathway projects</h3><ol><li>Complete the six steps and evidence requirements. Review the work product, tests, reflection and handover for accuracy.</li><li>When connected, save the current recipe to your account and submit the eligible revision from the project workflow. Use Projects & assessment to inspect its status and feedback.</li><li>A qualified reviewer assesses the submitted evidence within their approved subject scope. If changes are requested, improve the work, rerun checks and submit a new revision.</li><li>A different qualified verifier checks the review and evidence. Submitted or approved records remain protected from casual draft edits.</li><li>After all ten projects in a pathway meet the verified requirements, open Certificates. Read the public-name consent and request the eligible pathway certificate.</li></ol>
<h3>For professional missions</h3><p>Finish all twelve stages to preserve a mission attempt. Open <strong>Workspace sections → Reviews, records & payments → My submissions</strong>, select the preserved revision and use “Send this evidence.” Track the review there. Professional mission skill records and guided pathway certificates have separate eligibility requirements.</p>
${table(['Status','Meaning'],[['Draft / practiced','You have prepared work. This does not represent qualified approval.'],['Submitted / In Review','A preserved revision is awaiting assignment or being assessed.'],['Request Changes','Use the feedback to revise and submit again.'],['Pending Verification','The initial review needs an independent second check.'],['Verified','The evidence passed the required review and verification.']])}
<p>A sample certificate demonstrates the design only. An issued certificate includes its scope, issue record and verification link. Use that link to inspect its current status; a withdrawn certificate is not an active credential. Keep the supporting evidence with your portfolio.</p>
<div class="guide-actions">${action('Projects & assessment','#portfolio')}${action('Certificates','#certificates')}${action('Professional submissions','workspace.html?view=services')}</div>`},
{id:'saving',title:'Save, back up & return',intro:'Know where your work lives before changing devices or restoring a backup.',body:()=>`
${table(['Work','How to keep it'],[['Weekly learning plan','Saved in your account through My learning plan. Your selected format, course or programme, weekly hours, practice days and timezone are available across devices.'],['Guided recipes and session calendar','Saved in this browser as you work. Use Learning support → Export backup for the guided-learning backup. Connected recipes can also be saved explicitly to the cloud.'],['Guided project tools','Tool drafts use their own local storage. Export the actual work with the tool’s controls and include it with your project evidence.'],['Professional practice','Use Export practice backup at the top of the workspace. It contains the original mission drafts, notes and local records.'],['Professional cloud copy','When connected, open Reviews, records & payments → Save & recover → Save current workspace to cloud. Check the returned revision and time.']])}
<h3>Before closing a session</h3><ol><li>Confirm that the current draft shows as saved. If browser storage is full or unavailable, export before leaving.</li><li>Download the evidence or work product you want to keep. Store it in a clearly named project folder on your device.</li><li>If your account is connected, use the relevant cloud-save action and wait for its success message. Local autosave is not automatic cross-device sync.</li><li>Plan the next task so you can resume without guessing what remained unfinished.</li></ol>
<h3>Restore carefully</h3><p>Guided backups and professional practice backups use different formats. Restore a backup in the area that created it. Export your current work first because restoring can replace local draft content. Professional restored drafts require fresh checks; imported files cannot grant assessment approval.</p>
${note('Changing browsers, clearing site data or using private browsing can remove local drafts. Sign-in alone does not migrate preview work into your account. Export preview work before switching accounts or devices. Do not share a device session containing private learning evidence.')}
<div class="guide-actions">${action('Guided backup & support','#help')}${action('Professional evidence & restore','workspace.html?view=evidence')}${action('Professional cloud copy','workspace.html?view=services')}</div>`},
{id:'help',title:'Troubleshooting & support',intro:'Use the exact message and a small, repeatable example to find the next step.',body:()=>`
${[['I cannot continue to the next step.','Read the validation message and complete the named notes, criteria or current test. A brief sentence may not contain enough specific evidence. In professional practice, changing the work can invalidate tests; rerun them on the latest revision.'],['My draft seems missing.','Check that you are using the same browser, device and account. Preview drafts and signed-in drafts are separate. Restore the appropriate backup or cloud copy only after exporting the current local work.'],['I cannot sign in or register.','If registration is not open, identity setup is pending. Otherwise check the email, confirmation status and password. Use Forgot password for recovery; do not share passwords or email-link tokens in support requests.'],['The programme or pathway says access required.','Check the signed-in account and the exact scope of your purchase or assigned access. A registration, receipt sample or unrelated course purchase does not unlock every pathway.'],['My payment is still pending.','Open your owned order in Access & receipts and refresh its status. Keep the order reference if you need help. Avoid repeating payment while the first charge is unresolved.'],['I completed practice but have no certificate.','Practice, qualified review and independent verification are different milestones. Inspect each project’s status. A pathway certificate requires all its eligible projects to be verified.'],['The tool output looks wrong.','Reduce the input to a small fictional example, run again and record expected versus actual output. Check missing values, formatting, permissions and the simulator’s stated limits.'],['I need an adjustment or want to appeal.','Use the connected service request desk for accommodations, appeals and account or payment help. In preview, Support preparation creates a local request you can export; it does not send a message.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}
<h3>Prepare a useful help request</h3><ol><li>Name the pathway or programme, project or mission, and current step.</li><li>Describe what you expected, what happened and the exact message.</li><li>Include the smallest fictional example that reproduces the issue and what you have already tried.</li><li>Exclude passwords, payment card details, confirmation tokens and private client information.</li></ol>
<p><strong>Accessibility:</strong> use Tab to move through controls, Enter to follow links and Space to activate buttons. The first Tab reveals the skip link. Navigation works at narrow widths, form fields have labels, and animations respect reduced-motion preferences. Zoom the browser to a comfortable reading size.</p>
<div class="guide-actions">${action('Open service request desk','workspace.html?view=services')}${action('Prepare a local support request','workspace.html?view=support')}${action('Plain-language glossary','#glossary')}</div>`},
{id:'launch',title:'Administrator & teacher operations',intro:'Connect real commerce, appoint your team and deliver the paid teaching workflow.',body:()=>`
<h3>Administrator: launch in order</h3><ol><li>Open <strong>Launch & team</strong> using the verified owner account. Enter the business display name, support email and actual purchase terms.</li><li>Enter your Razorpay merchant key ID, key secret and webhook secret in the secure merchant form. A connection check verifies the credentials. Test-mode credentials do not open paid student enrolment. Your production host must allow public sign-in and signed payment notifications; enable live sales only after the owner has checked the merchant webhook.</li><li>Add the displayed HTTPS webhook to the same Razorpay account. Select payment.captured, order.paid, refund.processed, payment.dispute.created, payment.dispute.under_review and payment.dispute.lost, then configure automatic capture in the merchant dashboard.</li><li>Add course offers with your actual INR checkout prices, included courses, access duration, purchase terms and refund policy. Approve those details and set the offer to Live.</li><li>Record the real demo learner and six teachers by name and sign-in email. Set access expiry; teachers also need course scopes and checked qualifications. Ask each person to sign in using that exact email and complete registration.</li></ol>
<h3>Teacher: deliver the purchased bundle</h3><ol><li>Open <strong>Teacher workspace</strong>. The administrator assigns a qualified course teacher to a paid waiting package and agrees the eight-week start date.</li><li>Offer non-overlapping two-hour class times for the approved course and add the real Google Meet, Zoom or Teams link.</li><li>The student books available times through My teacher. The system checks the 24-class allowance, three classes per week and overlapping bookings.</li><li>After the booked class ends, record actual attendance, covered learning and the next task. Use meeting-link and cancellation controls for changes; recorded cancellations release the student’s allowance.</li></ol>
<h3>Access and payment records</h3><p>The full demo account covers learning courses, professional programmes and practice tools. It does not expose administration or other learners’ personal records. Teachers see their assigned packages and courses. A confirmed captured payment unlocks only the purchased scope. Refunds are handled in the merchant dashboard; a confirmed full refund withdraws that order’s learning access and future classes.</p>
<p>The on-screen payment receipt acknowledges payment. Use your commercial invoicing process for any required tax invoice. Teacher access and certificate assessment appointments remain separate.</p>
<div class="guide-actions">${action('Launch & team','#operations')}${action('Teacher workspace','#teaching-staff')}${action('My teacher','#teaching')}</div>`}
];
function render(id='start',mode='preview'){
 const index=Math.max(0,chapters.findIndex(c=>c.id===id)),c=chapters[index],prev=chapters[index-1],next=chapters[index+1];
 return `<div class="page-head"><div><h1>Your Academy guide.</h1><p>From your first sign-in to professional practice and a verified portfolio.</p></div><a class="btn" href="#home">Back to my learning →</a></div><div class="guide-layout"><nav class="guide-toc" aria-label="Academy guide chapters"><h2>In this handbook</h2>${chapters.map((x,i)=>`<a href="#guide/${x.id}" class="${i===index?'active':''}" ${i===index?'aria-current="page"':''}><span>${String(i+1).padStart(2,'0')}</span>${x.title}</a>`).join('')}</nav><article class="guide-article"><span class="label">ACADEMY HANDBOOK · ${String(index+1).padStart(2,'0')} / ${chapters.length}</span><h2>${c.title}</h2><p>${c.intro}</p>${c.body(mode)}<nav class="guide-pagination" aria-label="Chapter navigation">${prev?`<a class="text-link" href="#guide/${prev.id}">← ${prev.title}</a>`:'<span></span>'}${next?`<a class="text-link" href="#guide/${next.id}">Next: ${next.title} →</a>`:'<a class="text-link" href="#paths">Choose my next pathway →</a>'}</nav></article></div>`;
}
window.AcademyGuide={chapters,render};
})();
